CREATE TABLE uploads(id TEXT PRIMARY KEY CHECK(length(id)=36),owner_id TEXT NOT NULL REFERENCES member(user_id),source TEXT NOT NULL CHECK(source IN ('web','token','zenov')),format TEXT NOT NULL CHECK(format IN ('glb','gltf')),object_key TEXT NOT NULL UNIQUE,declared_bytes INTEGER NOT NULL CHECK(declared_bytes>0 AND declared_bytes<=52428800),declared_sha256 TEXT NOT NULL CHECK(length(declared_sha256)=64),status TEXT NOT NULL DEFAULT 'reserved' CHECK(status IN ('reserved','received','pending_scan','scanning','queued','rejected_auto','failed','expired')),reason TEXT,title TEXT CHECK(title IS NULL OR length(title) BETWEEN 1 AND 80),description TEXT CHECK(description IS NULL OR length(description)<=500),category TEXT CHECK(category IS NULL OR length(category)<=40),provenance TEXT CHECK(provenance IS NULL OR (json_valid(provenance) AND length(provenance)<=4096)),version_id TEXT REFERENCES asset_version(id),expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX uploads_owner_day ON uploads(owner_id,created_at);
CREATE TRIGGER uploads_owner_immutable BEFORE UPDATE OF owner_id,source,format,object_key,declared_bytes,declared_sha256,created_at ON uploads BEGIN SELECT RAISE(ABORT,'upload_identity_immutable'); END;
CREATE TABLE safety_report(id TEXT PRIMARY KEY,upload_id TEXT REFERENCES uploads(id),version_id TEXT REFERENCES asset_version(id),policy_version TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN ('pass','flag','reject','incomplete')),shadow INTEGER NOT NULL DEFAULT 1 CHECK(shadow IN (0,1)),summary TEXT NOT NULL CHECK(json_valid(summary)),report_sha256 TEXT NOT NULL CHECK(length(report_sha256)=64),created_at INTEGER NOT NULL,CHECK(upload_id IS NOT NULL OR version_id IS NOT NULL));
CREATE TRIGGER safety_report_immutable BEFORE UPDATE ON safety_report BEGIN SELECT RAISE(ABORT,'safety_report_immutable'); END;
CREATE TRIGGER safety_report_no_delete BEFORE DELETE ON safety_report BEGIN SELECT RAISE(ABORT,'safety_report_immutable'); END;
CREATE TABLE safety_finding(report_id TEXT NOT NULL REFERENCES safety_report(id),idx INTEGER NOT NULL CHECK(idx>=0),category TEXT NOT NULL CHECK(category IN ('sexual','child_like','hate_symbol','slur_text','violence','suspicious_instructions','hidden_geometry','invalid_file','analysis_incomplete')),detector TEXT NOT NULL CHECK(length(detector) BETWEEN 1 AND 60),band TEXT NOT NULL CHECK(band IN ('low','flag','reject')),artifact_path TEXT CHECK(artifact_path IS NULL OR length(artifact_path)<=250),bbox TEXT CHECK(bbox IS NULL OR json_valid(bbox)),text_span TEXT CHECK(text_span IS NULL OR length(text_span)<=200),PRIMARY KEY(report_id,idx));
CREATE TRIGGER safety_finding_immutable BEFORE UPDATE ON safety_finding BEGIN SELECT RAISE(ABORT,'safety_finding_immutable'); END;
CREATE TRIGGER safety_finding_no_delete BEFORE DELETE ON safety_finding BEGIN SELECT RAISE(ABORT,'safety_finding_immutable'); END;
CREATE TABLE review_queue(version_id TEXT PRIMARY KEY REFERENCES asset_version(id),priority INTEGER NOT NULL DEFAULT 0 CHECK(priority BETWEEN 0 AND 100),reason TEXT NOT NULL CHECK(reason IN ('pass','flag','appeal','incomplete','report','legacy')),claimed_by TEXT REFERENCES member(user_id),claim_expires_at INTEGER,revision INTEGER NOT NULL DEFAULT 0,enqueued_at INTEGER NOT NULL,decided_at INTEGER,decided_by TEXT REFERENCES member(user_id),CHECK((claimed_by IS NULL)=(claim_expires_at IS NULL)));
CREATE INDEX review_queue_order ON review_queue(decided_at,priority DESC,enqueued_at);
CREATE TABLE queue_event_log(seq INTEGER PRIMARY KEY AUTOINCREMENT,version_id TEXT NOT NULL,actor_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('enqueued','claimed','heartbeat','released','expired','decided','auto_outcome','override')),detail TEXT CHECK(detail IS NULL OR json_valid(detail)),created_at INTEGER NOT NULL);
CREATE INDEX queue_event_version ON queue_event_log(version_id,seq);
CREATE TRIGGER queue_event_log_append_only BEFORE UPDATE ON queue_event_log BEGIN SELECT RAISE(ABORT,'queue_event_log_append_only'); END;
CREATE TRIGGER queue_event_log_no_delete BEFORE DELETE ON queue_event_log BEGIN SELECT RAISE(ABORT,'queue_event_log_append_only'); END;
